Task: write a StableHLO program whose entry function has exactly this signature:
func.func @main(%idx: tensor<4xi32>) -> tensor<4x8xf32>

It must compute: out[n, c] = 1.0 if idx[n] == c else 0.0, for c < 8; a row whose idx is outside 0..7 is all zeros.

Relevant operations: iota, broadcast_in_dim, compare, select, constant.

Reply with the complete program in a single ```mlir code block.

```mlir
func.func @main(%idx: tensor<4xi32>) -> tensor<4x8xf32> {
  // Create an iota for the class dimension: shape [8], values 0..7
  %iota_c = "stablehlo.iota"() {iota_dimension = 0 : i64} : () -> tensor<8xi32>
  // Broadcast iota to shape [4,8] along dimension 1
  %iota_bc = "stablehlo.broadcast_in_dim"(%iota_c) {broadcast_dimensions = array<i64: 1>} : (tensor<8xi32>) -> tensor<4x8xi32>
  // Broadcast idx to shape [4,8] along dimension 0
  %idx_bc = "stablehlo.broadcast_in_dim"(%idx) {broadcast_dimensions = array<i64: 0>} : (tensor<4xi32>) -> tensor<4x8xi32>
  // Compare: idx_bc == iota_bc, result is tensor<4x8xi1>
  %eq = "stablehlo.compare"(%idx_bc, %iota_bc) {comparison_direction = #stablehlo<comparison_direction EQ>, compare_type = #stablehlo<comparison_type SIGNED>} : (tensor<4x8xi32>, tensor<4x8xi32>) -> tensor<4x8xi1>
  // Constants 1.0 and 0.0, shape [4,8]
  %one = "stablehlo.constant"() {value = dense<1.0> : tensor<4x8xf32>} : () -> tensor<4x8xf32>
  %zero = "stablehlo.constant"() {value = dense<0.0> : tensor<4x8xf32>} : () -> tensor<4x8xf32>
  // Select: if eq then 1.0 else 0.0
  %out = "stablehlo.select"(%eq, %one, %zero) : (tensor<4x8xi1>, tensor<4x8xf32>, tensor<4x8xf32>) -> tensor<4x8xf32>
  return %out : tensor<4x8xf32>
}
```

