  %v_bcast = "stablehlo.broadcast_in_dim"(%v) {broadcast_dimensions = array<i64: 1>} : (tensor<3xf32>) -> tensor<4x3x5xf32>
  // Subtract broadcasted %v from %x
  %out = stablehlo.subtract %x, %v_bcast : tensor<4x3x5xf32>
  return %out : tensor<4x3x5xf32>
}
