```mlir
module {
  func.func @main(%u: tensor<6xf32>, %v: tensor<3xf32>) -> tensor<6x3xf32> {
    // Broadcast %u from [6] to [6,3] along dimension 0
    %u_bcast = stablehlo.broadcast_in_dim %u, dims = [0] : (tensor<6xf32>) -> tensor<6x3xf32>
    // Broadcast %v from [3] to [6,3] along dimension 1
    %v_bcast = stablehlo.broadcast_in_dim %v, dims = [1] : (tensor<3xf32>) -> tensor<6x3xf32>
    // Elementwise multiply
    %out = stablehlo.multiply %u_bcast, %v_bcast : tensor<6x3xf32>
    return %out : tensor<6x3xf32>
  }
}
