    // Step 3: Take sqrt of the sum to get L2 norm for each row
    %l2norm = stablehlo.sqrt %sum : tensor<3xf32>

    // Step 4: Broadcast l2norm to shape (3,8) for division
    %l2norm_bcast = "stablehlo.broadcast_in_dim"(%l2norm) {broadcast_dimensions = array<i64: 0>} : (tensor<3xf32>) -> tensor<3x8xf32>

    // Step 5: Divide x by l2norm_bcast
    %out = stablehlo.divide %x, %l2norm_bcast : tensor<3x8xf32>

    return %out : tensor<3x8xf32>
  }
