      "stablehlo.return"(%add) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2>} : (tensor<6x5x2xf32>, tensor<f32>) -> tensor<6x5xf32>
  return %sum : tensor<6x5xf32>
}
