    %eq = stablehlo.compare(%idx_bcast, %iota_bcast), comparison_direction = "EQ" : (tensor<4x8xi32>, tensor<4x8xi32>) -> tensor<4x8xi1>
    // Check idx_bcast >= 0
    %zero = stablehlo.constant dense<0> : tensor<i32>
    %zero_bcast = stablehlo.broadcast_in_dim(%zero, dims = []) : (tensor<i32>) -> tensor<4x8xi32>
    %ge0 = stablehlo.compare(%idx_bcast, %zero_bcast), comparison_direction = "GE" : (tensor<4x8xi32>, tensor<4x8xi32>) -> tensor<4x8xi1>
    // Check idx_bcast < 8
    %eight = stablehlo.constant dense<8> : tensor<i32>
    %eight_bcast = stablehlo.broadcast_in_dim(%eight, dims = []) : (tensor<i32>) -> tensor<4x8xi32>
    %lt8 = stablehlo.compare(%idx_bcast, %eight_bcast), comparison_direction = "LT" : (tensor<4x8xi32>, tensor<4x8xi32>) -> tensor<4x8xi1>
    // Combine: valid = ge0 AND lt8
    %valid = stablehlo.and(%ge0, %lt8) : (tensor<4x8xi1>, tensor<4x8xi1>) -> tensor<4x8xi1>
    // Final mask: eq AND valid
    %mask = stablehlo.and(%eq, %valid) : (tensor<4x8xi1>, tensor<4x8xi1>) -> tensor<4x8xi1>
    // Select: if mask then 1.0 else 0.0
    %one = stablehlo.constant dense<1.0> : tensor<f32>
    %zero_f = stablehlo.constant dense<0.0> : tensor<f32>
    %one_bcast = stablehlo.broadcast_in_dim(%one, dims = []) : (tensor<f32>) -> tensor<4x8xf32>
    %zero_bcast_f = stablehlo.broadcast_in_dim(%zero_f, dims = []) : (tensor<f32>) -> tensor<4x8xf32>
    %out = stablehlo.select(%mask, %one_bcast, %zero_bcast_f) : (tensor<4x8xi1>, tensor<4x8xf32>, tensor<4x8xf32>) -> tensor<4x8xf32>
    return %out : tensor<4x8xf32>
