        "stablehlo.return"(%s) : (tensor<f32>) -> ()
    }) {dimensions = array<i64: 2>} : (tensor<4x2x5xf32>, tensor<f32>) -> tensor<4x2xf32>
    return %sum : tensor<4x2xf32>
