  %x_bcast = "stablehlo.broadcast_in_dim"(%x) {broadcast_dimensions = array<i64: 0,2>} : (tensor<2x5xf32>) -> tensor<2x3x5xf32>
  // Broadcast %y from [3,5] to [2,3,5] along dims [1,2]
  %y_bcast = "stablehlo.broadcast_in_dim"(%y) {broadcast_dimensions = array<i64: 1,2>} : (tensor<3x5xf32>) -> tensor<2x3x5xf32>
  // Subtract: (%x_bcast - %y_bcast)
  %diff = stablehlo.subtract %x_bcast, %y_bcast : tensor<2x3x5xf32>
  // Square: (%diff * %diff)
  %sq = stablehlo.multiply %diff, %diff : tensor<2x3x5xf32>
  // Constant zero for reduction init
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  // Reduce sum over dimension 2 (the 'd' dimension)
  %sum = "stablehlo.reduce"(%sq, %zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %add = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%add) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2>} : (tensor<2x3x5xf32>, tensor<f32>) -> tensor<2x3xf32>
  return %sum : tensor<2x3xf32>
}
