  func.func @main(%x: tensor<4x5xf32>) -> tensor<4x5xf32> {
    // Step 1: Compute exp(x)
    %exp_x = stablehlo.exp %x : tensor<4x5xf32>

    // Step 2: Reduce sum over dimension 1 (axis=1)
    // Need an initial value for sum: 0.0
    %zero = stablehlo.constant dense<0.0> : tensor<f32>
    %sum = stablehlo.reduce(%exp_x, %zero) across dimensions = [1] {
      ^bb0(%a: f32, %b: f32):
        %add = stablehlo.add %a, %b : f32
        stablehlo.return %add : f32
    } : (tensor<4x5xf32>, tensor<f32>) -> tensor<4xf32>

    // Step 3: Broadcast sum to shape [4,5] for division
    %sum_bcast = stablehlo.broadcast_in_dim %sum, dims = [0] : (tensor<4xf32>) -> tensor<4x5xf32>

    // Step 4: Divide exp(x) by broadcasted sum
    %softmax = stablehlo.divide %exp_x, %sum_bcast : tensor<4x5xf32>

    return %softmax : tensor<4x5xf32>
  }
}
