```mlir
module {
  func.func @main(%x: tensor<8x3xf32>) -> tensor<8xi32> {
    // Step 1: Create a tensor of zeros to compare against
    %zero = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
    %zeros = "stablehlo.constant"() {value = dense<0.0> : tensor<8x3xf32>} : () -> tensor<8x3xf32>

    // Step 2: Compare x > 0 elementwise
    %gt = "stablehlo.compare"(%x, %zeros) {comparison_direction = #stablehlo<comparison_direction GT>, compare_type = #stablehlo<comparison_type FLOAT>} : (tensor<8x3xf32>, tensor<8x3xf32>) -> tensor<8x3xi1>

    // Step 3: Convert boolean mask to i32 (0 or 1)
    %gt_i32 = "stablehlo.convert"(%gt) : (tensor<8x3xi1>) -> tensor<8x3xi32>

    // Step 4: Reduce-sum along axis 1 (columns) to count number of positives per row
    %zero_i32 = "stablehlo.constant"() {value = dense<0> : tensor<i32>} : () -> tensor<i32>
    %out = "stablehlo.reduce"(%gt_i32, %zero_i32) ({
      ^bb0(%a: tensor<i32>, %b: tensor<i32>):
        %s = "stablehlo.add"(%a, %b) : (tensor<i32>, tensor<i32>) -> tensor<i32>
        "stablehlo.return"(%s) : (tensor<i32>) -> ()
    }) {dimensions = array<i64: 1>} : (tensor<8x3xi32>, tensor<i32>) -> tensor<8xi32>

    return %out : tensor<8xi32>
  }
}
