  func.func @main(%x: tensor<4x3xf32>) -> tensor<4x3xf32> {
    // Square each element: x^2
    %x2 = stablehlo.multiply %x, %x : tensor<4x3xf32>

    // Initial value for sum: 0.0
    %zero = stablehlo.constant dense<0.0> : tensor<f32>

    // Reduce sum over axis 1 (columns), keep axis 0 (rows)
    %sum = "stablehlo.reduce"(%x2, %zero) ({
      ^bb0(%a: tensor<f32>, %b: tensor<f32>):
        %add = stablehlo.add %a, %b : tensor<f32>
        "stablehlo.return"(%add) : (tensor<f32>) -> ()
    }) {dimensions = array<i64: 1>} : (tensor<4x3xf32>, tensor<f32>) -> tensor<4xf32>

    // Take sqrt of the sum: sqrt(sum_k x[i, k]^2)
    %sqrt = stablehlo.sqrt %sum : tensor<4xf32>

    // Broadcast sqrt to shape (4,3) along axis 0
    %sqrt_bcast = "stablehlo.broadcast_in_dim"(%sqrt) {broadcast_dimensions = array<i64: 0>} : (tensor<4xf32>) -> tensor<4x3xf32>

    // Divide x by sqrt_bcast
    %out = stablehlo.divide %x, %sqrt_bcast : tensor<4x3xf32>

    return %out : tensor<4x3xf32>
  }
}
