Relevant operations: reduce, broadcast_in_dim, element-wise ops (add/subtract/multiply/divide/maximum/minimum/negate/exponential/sqrt/rsqrt/abs), constant.

Reply with the complete program in a single ```mlir code block.

```mlir
func.func @main(%x: tensor<4x5xf32>) -> tensor<4x5xf32> {
  // Compute exp(x)
  %exp_x = stablehlo.exponential %x : tensor<4x5xf32>

  // Prepare the zero constant for sum reduction
  %zero = stablehlo.constant dense<0.0> : tensor<f32>

  // Sum over dimension 1 (axis=1)
  %sum = "stablehlo.reduce"(%exp_x, %zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %add = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%add) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<4x5xf32>, tensor<f32>) -> tensor<4xf32>

  // Broadcast sum back to shape [4,5]
  %sum_broadcast = "stablehlo.broadcast_in_dim"(%sum) {broadcast_dimensions = array<i64: 0>} : (tensor<4xf32>) -> tensor<4x5xf32>

  // Divide exp(x) by sum_k exp(x)
  %softmax = stablehlo.divide %exp_x, %sum_broadcast : tensor<4x5xf32>

  return %softmax : tensor<4x5xf32>
}
