    %norm_b = "stablehlo.broadcast_in_dim"(%norm) {broadcast_dimensions = array<i64: 0>} : (tensor<7xf32>) -> tensor<7x3xf32>

    // Step 5: Divide input by norm (row-wise normalization)
    %out = stablehlo.divide %x, %norm_b : tensor<7x3xf32>

    return %out : tensor<7x3xf32>
  }
}
